if __name__ == "__main__":
    ids = [json.loads(l)["mid"] for l in open("data/z52b/pass1/batch_U05.jsonl")]
    old = {json.loads(l)["mid"]: json.loads(l) for l in open("data/z52b/pass1/outcome_U05.jsonl")}
    new = []
    for m in ids:
        if m in R:
            o, summ, ev, nxt = R[m]
            new.append({"mid": m, "outcome": o, "summary": summ, "evidence": ev, "next": nxt})
        else:
            new.append(old[m])
    left = [r["mid"] for r in new if r["outcome"] in ("skipped", "needs-compute")]
    print("lines:", len(new), "remaining skipped/needs:", left)
    from collections import Counter
    print(Counter(r["outcome"] for r in new))
    with open("data/z52b/pass1/outcome_U05.jsonl", "w") as f:
        for r in new: f.write(json.dumps(r, ensure_ascii=False) + "\n")
